<div class="mb-4"><h1 class="h3 mb-1">Ticket categories</h1><p class="text-secondary">Inactive categories stay attached to existing tickets.</p></div><div class="card mb-3"><div class="card-header">Add category</div><div class="card-body"><form method="post" action="<?= site_url('admin/categories') ?>" class="row g-2 align-items-end"><?= csrf_field() ?><div class="col-md-8"><label class="form-label" for="new-name">Category name</label><input class="form-control" id="new-name" name="name" maxlength="80" required></div><div class="col-md-4"><button class="btn btn-primary">Add category</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Category</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><form class="d-flex gap-2" method="post" action="<?= site_url('admin/categories/' . $category['id']) ?>"><?= csrf_field() ?><label class="visually-hidden" for="cat<?= (int) $category['id'] ?>">Category name</label><input class="form-control form-control-sm" id="cat<?= (int) $category['id'] ?>" name="name" value="<?= esc($category['name']) ?>" maxlength="80" required><button class="btn btn-sm btn-outline-primary">Save name</button></form></td><td><?= $category['is_active'] ? 'Active' : 'Inactive' ?></td><td><form method="post" action="<?= site_url('admin/categories/' . $category['id'] . '/status') ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-secondary"><?= $category['is_active'] ? 'Deactivate' : 'Activate' ?></button></form></td></tr><?php endforeach ?></tbody></table></div></div>
